export type UiKey = keyof typeof dictionaries.en | keyof typeof extras.en | keyof typeof finderExtras.en | keyof typeof detailExtras.en;

export function uiText(locale: Locale, key: UiKey): string {
  const primary = (dictionaries[locale] as Record<string, string>)[key];
  const secondary = (extras[locale] as Record<string, string>)[key];
  const finder = (finderExtras[locale] as Record<string, string>)[key];
  const detail = (detailExtras[locale] as Record<string, string>)[key];
  const fallback = (dictionaries.en as Record<string, string>)[key]
    || (extras.en as Record<string, string>)[key]
    || (finderExtras.en as Record<string, string>)[key]
    || (detailExtras.en as Record<string, string>)[key];
  return primary || secondary || finder || detail || fallback || key;
}
